python3 << 'EOF'
import json
# Check all products for competitor discussions
import os
products_dir = 'DATA/products'
all_discussions = {}
for fname in os.listdir(products_dir):
    if fname.endswith('.json'):
        with open(os.path.join(products_dir, fname)) as f:
            data = json.load(f)
        competitor_mentions = []
        if 'slack' in data:
            for i, msg in enumerate(data['slack']):
                text = msg.get('Message', {}).get('User', {}).get('text', '') or ''
                # Only PersonalizeForce competitor-related
                if 'TailorAI' in text or 'PersonaAI' in text or 'SmartSuggest' in text:
                    user_id = msg.get('Message', {}).get('User', {}).get('userId', '')
                    channel_name = msg.get('Channel', {}).get('name', '')
                    competitor_mentions.append((i, user_id, channel_name, text[:200]))
        if competitor_mentions:
            all_discussions[fname] = competitor_mentions
            print(f'=== {fname} ===')
            for i, user_id, channel_name, text in competitor_mentions:
                print(f'[{i}][{channel_name}][{user_id}]: {text}')
            print()
EOF

